// src/components/CashflowFluctuation.jsx
import React, { useState } from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

export default function CashflowFluctuation() {
  // State điều khiển các Tab lựa chọn
  const [timeframe, setTimeframe] = useState('thang'); // 'tuan' | 'thang' | 'nam'
  const [metric, setMetric] = useState('chitieu');     // 'thunhap' | 'chitieu' | 'chenhlech'
  const [comparePeriod, setComparePeriod] = useState(true);

  // Dữ liệu mẫu mô phỏng giống ảnh chụp màn hình
  const labels = ['T1', 'T2', 'T3', 'T4', 'T5', 'T6', 'Tháng này'];
  
  // Bộ dữ liệu thực tế (tháng này cao bật lên giống ảnh)
  const currentData = [200000, 350000, 2600000, 800000, 1050000, 1600000, 2314745];
  // Bộ dữ liệu cùng kỳ (nền màu nhạt hơn phía sau)
  const previousData = [250000, 180000, 2750000, 900000, 1150000, 2650000, 1546184];

  // Cấu hình dữ liệu cho Chart.js
  const chartData = {
    labels,
    datasets: [
      {
        label: metric === 'chitieu' ? 'Chi tiêu hiện tại' : metric === 'thunhap' ? 'Thu nhập hiện tại' : 'Chênh lệch',
        data: currentData,
        backgroundColor: labels.map((_, index) =>
          index === labels.length - 1 ? '#007aff' : '#7cb9ff' // Cột cuối màu xanh đậm giống UI mẫu
        ),
        borderRadius: 6,
        barPercentage: 0.7,
        order: 1,
      },
      // Nếu bật "So với cùng kỳ" thì hiện thêm cột nền nhạt
      ...(comparePeriod
        ? [
            {
              label: 'Cùng kỳ trước',
              data: previousData,
              backgroundColor: '#d6e8ff',
              borderRadius: 6,
              barPercentage: 0.9,
              order: 2,
            },
          ]
        : []),
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false, // Ẩn legend mặc định để tự làm custom bên dưới cho đẹp
      },
      tooltip: {
        backgroundColor: '#1e293b',
        titleFont: { size: 13, family: 'sans-serif' },
        bodyFont: { size: 12, family: 'sans-serif', weight: 'bold' },
        padding: 10,
        cornerRadius: 8,
        callbacks: {
          label: (context) => `${context.dataset.label}: ${context.raw.toLocaleString('vi-VN')}đ`,
        },
      },
    },
    scales: {
      x: {
        grid: { display: false },
        ticks: { font: { weight: '600', size: 12 }, color: '#64748b' },
      },
      y: {
        grid: { color: '#f1f5f9' },
        ticks: {
          callback: (value) => `${(value / 1000000).toFixed(1)} Tr`,
          font: { size: 11 },
          color: '#94a3b8',
        },
      },
    },
  };

  return (
    <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-slate-800 text-gray-800 dark:text-gray-100 transition-colors">
      
      {/* 1. THANH CHỌN THỜI GIAN: TUẦN / THÁNG / NĂM */}
      <div className="flex justify-center mb-4">
        <div className="inline-flex bg-gray-100 dark:bg-slate-800 p-1.5 rounded-2xl w-full sm:w-auto">
          {['tuan', 'thang', 'nam'].map((tab) => (
            <button
              key={tab}
              onClick={() => setTimeframe(tab)}
              className={`flex-1 sm:px-8 py-2 rounded-xl text-sm font-bold transition-all ${
                timeframe === tab
                  ? 'bg-white dark:bg-slate-700 text-pink-600 dark:text-pink-400 shadow-sm'
                  : 'text-gray-500 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
              }`}
            >
              {tab === 'tuan' && 'Theo tuần'}
              {tab === 'thang' && 'Theo tháng'}
              {tab === 'nam' && 'Theo năm'}
            </button>
          ))}
        </div>
      </div>

      {/* 2. THANH CHỌN CHỈ SỐ: THU NHẬP / CHI TIÊU / CHÊNH LỆCH */}
      <div className="flex justify-center mb-6 border-b border-gray-100 dark:border-slate-800 pb-4">
        <div className="inline-flex gap-2">
          {[
            { id: 'thunhap', label: 'Thu nhập' },
            { id: 'chitieu', label: 'Chi tiêu' },
            { id: 'chenhlech', label: 'Chênh lệch' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setMetric(item.id)}
              className={`px-5 py-2 rounded-xl text-sm font-semibold transition ${
                metric === item.id
                  ? 'bg-pink-50 dark:bg-pink-950/40 text-pink-600 dark:text-pink-400 border border-pink-200 dark:border-pink-800'
                  : 'text-gray-500 hover:bg-gray-50 dark:hover:bg-slate-800'
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>
      </div>

      {/* 3. HIỂN THỊ SỐ TỔNG & BADGE TĂNG GIẢM SO VỚI CÙNG KỲ */}
      <div className="text-center mb-6">
        <p className="text-xs text-gray-500 dark:text-gray-400 font-medium">
          {metric === 'chitieu' && 'Tổng chi tháng này'}
          {metric === 'thunhap' && 'Tổng thu tháng này'}
          {metric === 'chenhlech' && 'Chênh lệch tháng này'}
        </p>
        <h3 className="text-3xl font-black text-gray-900 dark:text-white mt-1 tracking-tight">
          2.314.745đ
        </h3>
        <div className="inline-flex items-center gap-1.5 mt-2 px-3 py-1 bg-amber-50 dark:bg-amber-950/50 text-amber-600 dark:text-amber-400 border border-amber-200 dark:border-amber-800/60 rounded-full text-xs font-semibold">
          <span>↑</span>
          <span>Tăng 768.561đ so với cùng kỳ tháng trước</span>
          <span className="cursor-pointer font-bold">ⓘ</span>
        </div>
      </div>

      {/* 4. TIÊU ĐỀ BIỂU ĐỒ & NÚT GẠT SO VỚI CÙNG KỲ */}
      <div className="flex items-center justify-between mb-4 px-2">
        <span className="text-base font-bold text-gray-800 dark:text-gray-200">Biến động</span>
        <label className="inline-flex items-center cursor-pointer gap-2.5">
          <span className="text-xs font-semibold text-gray-500 dark:text-gray-400">So với cùng kỳ</span>
          <div
            onClick={() => setComparePeriod(!comparePeriod)}
            className={`w-11 h-6 flex items-center rounded-full p-1 transition duration-300 ${
              comparePeriod ? 'bg-emerald-500' : 'bg-gray-300 dark:bg-slate-700'
            }`}
          >
            <div
              className={`bg-white w-4 h-4 rounded-full shadow-md transform transition duration-300 ${
                comparePeriod ? 'translate-x-5' : ''
              }`}
            ></div>
          </div>
        </label>
      </div>

      {/* 5. KHUNG BIỂU ĐỒ CỘT */}
      <div className="h-64 w-full relative">
        <Bar data={chartData} options={chartOptions} />
      </div>

      {/* 6. CHÚ THÍCH MÀU (CUSTOM LEGEND) */}
      <div className="flex justify-center items-center gap-6 mt-4 pt-4 border-t border-gray-100 dark:border-slate-800 text-xs font-medium text-gray-500 dark:text-gray-400">
        <div className="flex items-center gap-2">
          <span className="w-3 h-3 rounded bg-[#007aff] inline-block"></span>
          <span>{metric === 'chitieu' ? 'Chi tiêu trong tháng' : 'Thực tế tháng này'}</span>
        </div>
        {comparePeriod && (
          <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded bg-[#d6e8ff] inline-block"></span>
            <span>Cùng kỳ trước</span>
          </div>
        )}
      </div>

    </div>
  );
}
